 amount) external returns (bool); function permit(address target, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external; function transferFrom(address sender, address recipient, uint256 amount) external returns (bool); function transferWithPermit(address target, address to, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external returns (bool); event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); } contract AnyswapV4Router { using SafeMathSushiswap for uint; address public immutable factory; address public immutable wNATIVE; modifier ensure(uint deadline) { require(deadline >= block.timestamp, 'AnyswapV3Router: EXPIRED'); _; } constructor(address _factory, address _wNATIVE, address _mpc) { _newMPC = _mpc; _newMPCEffectiveTime = block.timestamp; factory = _factory; wNATIVE = _wNATIVE; } receive() external payable { assert(msg.sender == wNATIVE); } address private _oldMPC; address private _newMPC; uint256 private _newMPCEffectiveTime; event LogChangeMPC(address indexed oldMPC, address indexed newMPC, uint indexed effectiveTime, uint chainID); event LogChangeRouter(address indexed oldRouter, address indexed newRouter, uint chainID); event LogAnySwapIn(bytes32 indexed txhash, address indexed token, address indexed to, uint amount, uint fromChainID, uint toChainID); event LogAnySwapOut(address indexed token, address indexed from, address indexed to, uint amount, uint fromChainID, uint toChainID); event LogAnySwapTradeTokensForTokens(address[] path, address indexed from, address indexed to, uint amountIn, uint amountOutMin, uint fromChainID, uint toChainID); event LogAnySwapTradeTokensForNative(address[] path, address indexed from, address indexed to, uint amountIn, uint amountOutMin, uint fromChainID, uint toChainID); modifier onlyMPC() { require(msg.sender == mpc(), "AnyswapV3Router: FORBIDDEN"); _; } function mpc() publ